"""Plain-language help shared by every page, action, and input."""

HELP = {}


def add(names, text):
    for name in names.split("|"):
        HELP[name] = text


add("使用说明", "每个按钮和填写项旁边都有一个‘？’，点击它可以看懂这个功能是做什么的、什么时候用、会改动什么。看说明不会执行操作。\n\n先添加服务器并连接检查，再选择你需要的功能。服务器名字、账号、密码、端口都是分开设置的；不知道某一项怎么填，可以先点它旁边的‘？’。危险操作还会再次确认。")
add("填写必要信息，其余交给程序|连接并检查", "填好服务器地址、登录账号和密码或私钥后，点击连接。程序会检查登录和管理员权限，并读取服务器状态。\n\n连接成功后，即使暂时不操作也会保持连接。短暂掉线会自动重连；切换页面或另一台服务器不会断开已连接的服务器。手动断开或关闭程序才结束这些连接。\n\n重连只恢复通道，不会重新执行安装、改密码等操作。身份变化或登录信息失效时停止重连，等待你核实。首次连接仍需确认服务器身份，不会降低身份检查要求。")
add("断开连接", "断开当前选中的服务器连接，并停止自动重连。其他已经连接的服务器继续保持。\n\n登录档案和本机保存的口令不会被删除，服务器项目也不会停止。需要再次使用时点击‘连接并检查’。关闭程序会断开本程序保持的所有连接。")
add("保存的服务器|服务器备注", "备注是你给这条连接起的名字，比如‘测试服务器·管理员’。它不会修改服务器的系统名字。\n\n同一台服务器可以保存多个账号，分别起不同备注；不同服务器也各自保存。操作前先确认当前选中的是哪条连接。")
add("添加新服务器", "打开连接设置，新增一条独立的连接档案。填服务器地址和要登录的账号即可；同一台服务器的另一个账号也用这个按钮添加。\n\n现有档案和项目不受影响。保存后会出现在左侧服务器列表，下次点击即可使用保存的信息连接。")
add("服务器地址", "填写云平台给你的公网 IP 或域名，不要加 http:// 或 https://。这个地址告诉程序要连接哪台电脑。\n\n请在云平台核对地址，避免连接错服务器。界面默认隐藏地址，可以用右上角开关查看。")
add("登录账号|账号名|验证登录账号", "这是 Linux 系统的登录用户名，和项目网页里的账号是两回事。云平台镜像的默认账号可能是普通管理员，也可能是超级管理员。\n\n选择账号后，密码、密钥和权限都属于这个账号。要禁用或删除默认账号，先创建并验证另一个普通管理员，再切换到新管理员操作。")
add("SSH 端口|SSH 端口（TCP）", "SSH 是本程序连接服务器的通道，使用 TCP，通常是 TCP 22，不需要开放 UDP。\n\n改端口时，程序先保留原端口并验证新端口。云平台安全组也要按 TCP 放行新端口。改端口不能代替强密码和密钥。")
add("登录方式", "密码登录：用服务器账号的密码开门。密钥登录：用这台电脑保存的私钥开门。\n\n这里选择本程序怎么连接。要让服务器禁止密码登录，需要到‘账号与登录’应用 SSH 设置；只改这里不会改变服务器政策。")
add("登录密码", "填写这个 Linux 账号现在使用的密码，不是程序密码或项目网页密码。修改系统密码要到‘账号与登录’操作。\n\n勾选记住登录信息后，密码保存在本机钥匙串，不放进普通档案文件，也不会随安装包发给别人。")
add("SSH 私钥|选择文件", "私钥相当于一把实体钥匙，通常是本机的一个文件。选择私钥文件，不能选择以 .pub 结尾的公钥。\n\n服务器必须已经允许与它配对的公钥登录。程序也能生成本机专用密钥并自动配置。请备份私钥；它不会上传到服务器。")
add("私钥口令（如有）", "有些私钥自己也有密码，用来保护钥匙文件。如果生成私钥时没有设置口令，这里留空。\n\n它不是 Linux 账号密码。勾选记住登录信息时可以保存在本机钥匙串。")
add("管理员密码（如不同）", "普通管理员执行安装或安全设置时，可能需要 sudo 密码。一般就是登录密码，相同就留空；不同才填写。\n\n程序会验证管理员权限，普通用户没有权限时不能直接进行系统改动。")
add("记住登录信息（仅本机）|保存连接档案", "保存这条连接，之后选择它即可自动填好登录信息。勾选记住时，登录密码、私钥口令和管理员密码放进本机 macOS 钥匙串；地址、账号和私钥位置放进仅本机可读的档案。\n\n不启用云端同步。换电脑需要重新配置。取消记住后会删除这一条保存的口令，私钥文件保留。请保护好这台电脑的登录账号。")
add("隐藏连接与账号信息|显示 / 隐藏", "把地址、账号和口令显示成圆点，适合录屏、截图或身边有别人时使用。再次点击可以查看。\n\n隐藏只改变显示，不会清空输入，也不影响连接。不要把显示出来的密码或私钥截图发送给别人。")
add("VNC 登录排查|复制只读检查命令", "VNC 是云平台的控制台入口，SSH 是另一种远程连接方式，两者允许的登录方法可能不同。\n\n先核对账号、端口和云平台安全组。如果 SSH 完全没开启，本程序也不能绕过云平台限制。排查窗口里的命令只查看设置，不会改配置。")
add("重新确认服务器身份", "服务器有自己的身份指纹，类似身份证号。重装或重建服务器后，它可能变化；换用户名不会让它变化。\n\n先在云平台核实地址仍对应自己的服务器，再点击这里更新身份记录。原记录会保留，随后重新验证登录。没有核实时不要确认陌生身份。")
add("多台服务器，一处管理|多台服务器，各自保存登录信息|检查全部服务器", "这里集中显示保存的服务器和账号。每一条连接的登录信息、身份记录、检查结果都独立保存。\n\n检查全部只依次读取状态，不修改服务器。新服务器仍要先单独确认身份。缺少口令或权限时会提示，不会猜密码。管理操作每次只针对当前选中的连接。")
add("切换到选中服务器|我的服务器", "左侧保存多台服务器的登录档案。点击一条即可使用本机保存的登录信息连接；已有可用连接会继续使用，不需要重复输入密码。首次连接仍需确认身份，保存的口令失效时需要重新填写。\n\n每次管理只针对当前选中的服务器，顶部始终显示当前备注。切换不会断开其他已有连接，也不会同步安装或修改其他服务器。执行任务时不能切换，避免操作错机器。同一服务器的不同账号仍可分别保存。")
add("移除本机档案", "删除选中连接的本机档案和保存的口令，不会删除服务器、Linux 用户或项目。\n\n私钥文件和操作记录保留，避免影响其他账号共用的钥匙。如果只是暂时不用，可以不删除。")
add("项目与配套服务|服务器总览|重新检查", "查看系统、磁盘、内存、项目运行情况和安全设置。重新检查会再次读取当前服务器的实际状态。\n\n这个页面不会启停服务。它显示的是最近一次检查结果，不代表一直在实时监控。")
add("账号、密码和连接方式", "这里管理 Linux 系统账号及 SSH 入口。推荐先创建自己的普通管理员并验证登录，再禁用默认账号和超级管理员直接登录。\n\n改变登录方式前，先配置并验证密钥。禁用、删除当前正在使用的账号会被拦住。连接相关变更会备份，验证失败时尝试恢复。")
add("新密码|再次输入", "输入新系统密码，再输入一次避免打错。新密码至少 12 个字符，可以使用较长的随机密码。\n\n修改系统密码不会修改项目网页账号或私钥口令。点击「生成密码」会同步填好两处。确认执行前先将新密码副本存入本机钥匙串，保存或回读失败就不提交。记住登录信息的档案在验证成功后同步更新；没有该账号的档案也能在「操作记录 → 查看本次新密码」找回。")
add("创建管理员", "建立一个新的普通管理员账号，设置密码，加入 sudo 管理员组，并可自动配置本机专用密钥。\n\n程序会用新账号验证登录及管理员权限，成功后切换使用。它是禁用默认账号前的第一步。超级管理员账号保留。")
add("创建账号时配置本机专用密钥|添加本机专用密钥并验证", "程序在本机生成私钥，把配对的公钥放到服务器，并用新钥匙实际测试登录。你不用复制命令。\n\n私钥留在本机，现有公钥会保留。确认新钥匙可用后，再禁止密码登录。请备份这台电脑的私钥文件。")
add("修改密码", "更改选中 Linux 账号的系统密码，其他账号不受影响。程序会检查新密码是否已经生效。\n\n它不会自动禁止密码登录；想只允许密钥，另行应用 SSH 设置。与这个账号对应的本机档案会更新保存的密码。")
add("改名后的账号|账号改名", "给普通账号换名字，同时移动标准家目录，保留原来的用户编号、文件权限和密钥。\n\n正在用这个账号登录时，原会话会关闭，程序再验证新账号。该账号仍在运行业务进程时会停止改名。超级管理员和系统服务账号不能改名。")
add("禁止用户登录", "禁止选中账号通过 SSH 登录，并锁住它的系统密码。账号和文件仍保留，已运行的服务和已有会话不会被强制停止。\n\n先用另一个已验证的普通管理员连接。不能禁用当前账号、超级管理员或系统服务账号。后续可恢复由本程序禁用的账号。")
add("恢复用户登录", "撤销本程序对这个账号设置的登录禁用。账号、文件和原有密钥继续使用。\n\n只恢复本程序施加的限制；如果账号原来就没有可用密码，或其他配置仍禁止它登录，不会擅自打开那些限制。")
add("删除用户（保留文件）", "把选中的普通账号从 Linux 系统中删除，它将不能再登录。默认保留家目录和文件。\n\n必须先切换到另一个已验证的普通管理员。账号有运行进程、服务或定时任务时会拒绝删除。超级管理员、系统账号和当前账号不能删。删除前会备份账号资料，待新连接验证后才完成。")
add("允许密码登录", "勾选后，服务器允许账号密码方式通过 SSH 登录。取消后，需要使用有效 SSH 密钥。\n\n取消前应勾选添加本机专用密钥并验证，或已经选择能用的私钥。程序会关闭键盘交互密码入口，验证新的连接方式；失败时尝试恢复。")
add("允许超级管理员直接登录", "超级管理员拥有最高权限。关闭后，不能再以超级管理员身份直接通过 SSH 登录。\n\n请先创建并验证能够 sudo 的普通管理员。普通管理员仍能完成安装和维护，系统中的超级管理员账号不会被删除。")
add("检查并应用 SSH 设置", "应用本页选定的登录方式、账号密钥和 SSH 端口。程序先备份，再用新连接验证登录及管理员权限。\n\n新端口暂时保留旧端口。云平台安全组也要放行新端口。验证失败时会尝试恢复原设置。")
add("常用安全设置", "这里补充防火墙、自动安全更新、防猜密码及 SSH 连接限制。每个设置都有自己的说明，不会因为打开这个页面就自动生效。\n\n先检查当前状态，再选择要应用的项目。不会自动重启服务器，也不会停止业务服务。")
add("单次连接允许尝试次数|应用 SSH 防护设置", "限制一次 SSH 连接可以尝试多少次认证，并设置连接等待和转发功能。尝试次数太少，密钥多的客户端可能连接失败。\n\n程序只修改这里列出的 SSH 项目，保留端口和登录方式；随后验证连接，失败时尝试恢复。空密码始终禁止。")
add("完成登录的等待秒数", "连接到服务器后，必须在这个时间内完成认证。超时会关闭这次尚未登录的连接。\n\n它不会限制已经登录后的工作时间。网速慢或需要手动确认密钥时，可以留长一点。")
add("断线检查间隔秒数", "服务器定时确认 SSH 客户端是否还有响应，连续没有响应时清理断开的会话。\n\n它用于发现断线，不是‘多久不操作就退出’。正常连接上的用户不会因为没敲键盘就被登出。")
add("允许 SSH 隧道转发", "SSH 隧道可以把本机或远端端口连起来，适合访问只在服务器内部开放的管理服务。\n\n不使用 SSH 隧道时可以关闭。关闭会影响依赖 SSH 转发的工具，但不会关闭独立运行的网络代理项目。")
add("允许图形界面转发", "通过 SSH 把服务器上的图形程序显示到本机，需要额外的图形环境。多数服务器管理不需要它。\n\n关闭后，普通命令行登录仍可用，独立项目网页不受影响。")
add("允许转交本机密钥代理", "让服务器借用本机的 SSH 密钥代理去连接其他机器，不会直接复制私钥，但会扩大服务器能使用钥匙的范围。\n\n不需要跳板或多段 SSH 登录时建议关闭。关闭后本机直接连接当前服务器仍可用。")
add("防猜密码保护|启用防猜密码保护", "安装并启用 Fail2ban，发现某个地址反复登录失败时，临时封住它的 SSH 访问。\n\n它会按当前 SSH 端口工作，不会替代密钥登录或防火墙。当前连接验证失败时会尝试恢复原配置。已有其他防护规则会保留。")
add("关闭本程序的防猜密码保护", "关闭本程序管理的 SSH 防猜密码配置。其他已有 Fail2ban 配置保留。\n\n关闭后，反复尝试密码的地址不再被这一项临时封禁。普通 SSH 密钥和密码规则保持原样。")
add("连续失败次数", "在统计时间内，某个地址登录失败达到这个次数，就临时封禁。\n\n建议给自己留出输错密码的余地。程序会进行新的连接验证。")
add("统计时间（分钟）", "防猜密码保护回看这段时间里的失败次数。比如 10 分钟内失败 5 次就临时封禁。\n\n这个时间不是封禁时长，也不是正常登录会话的时长。")
add("封禁时长（分钟）", "触发防猜密码保护后，这个地址暂时不能通过 SSH 连接，时间到了自动解除。\n\n不要把它设置得过长，避免自己输错密码后长时间无法登录。云平台控制台是备用入口。")
add("启用防火墙并保留现有规则", "防火墙决定哪些外部网络连接能进入服务器。程序会保留已有规则，并先放行 TCP SSH 和检测到的常用业务端口，再开启默认拒绝其他入口。确认窗口列出本次真正放行的端口和 TCP / UDP 协议。\n\nHY2 节点使用 UDP；网页和面板入口使用 TCP；需要两种协议的节点要分别放行 TCP 和 UDP。自定义端口需先有放行规则。云平台安全组是独立设置，也要按对应协议放行。验证失败时尝试恢复原防火墙配置。")
add("开启自动安全更新", "让系统按计划自动安装安全补丁，减少长期不更新留下的漏洞。程序会检查实际生效的更新配置，启用软件源刷新和安全更新定时器，并验证下一次计划；关机辅助服务正在运行不代表更新已启用。\n\n从下一次计划开始，不立即补跑过去漏掉的升级，自动重启保持关闭。沿用系统的软件源策略，不自动切换本程序安装的业务项目版本；安全补丁可能重启受影响的系统服务。必要的整机重启可自行安排维护时间。配置或调度验证失败会尝试恢复原设置。")
add("选择项目，点击部署|预览并部署", "没装过就安装；装过就比对你填写的新条件。条件相同不重复安装，只改端口或密码就调整对应配置，版本变化则先备份再切换。点击后会列出实际改动，确认才执行。\n\n四个项目都适用。原账号、节点和业务数据保留，新配置检查失败会恢复原项目。交易系统维护前先在网页停止交易、完成撤单和清理；安装不会自动开始交易。证书申请可能需要云平台放行 TCP 80。无法识别的旧安装会保留现场并提示处理，不能清空业务数据强行重装。")
add("要安装的项目", "选择项目后，只显示这个项目需要填写的信息。\n\n小军交易系统确认访问端口即可；程序密码在首次打开网页时设置，至少 8 位，初始化码在「查看访问 / 连接信息」获取。Hysteria2 首次需要端口和服务密码；代理面板首次需要端口、面板账号和密码；Nginx 确认端口，默认 80。已有项目自动带入现有设置，代理密码不改时可以留空。\n\n交易系统会安装并配置自己的 Nginx，通常不必先单独装 Nginx。再次部署可修改现有配置，或按你确认的版本升级、降级。")
add("访问域名（可留空）", "想通过域名访问项目，就填已经指向服务器的域名；留空则使用当前服务器地址。\n\n程序会按这个地址配置证书。域名没有正确指向服务器，或者云平台没开放证书验证端口时，申请会失败。")
add("服务端口", "这是项目对外提供服务的入口，旁边会标出对应协议，修改端口后下方放行提示同步更新。\n\nHysteria2 / HY2 节点：仅 UDP，不需要 TCP。小军交易网页、代理管理面板网页及本程序默认 Nginx 网页：仅 TCP，不需要 UDP。面板网页端口不是代理节点端口；每个节点按实际配置使用 TCP、UDP 或两者，在「运行与备份」查看。代理可转发 UDP 流量，不等于公网入口一定需要 UDP。\n\n服务器防火墙和云平台安全组都要按对应协议允许端口；若标出 TCP + UDP，两者都需放行。自动申请和续期证书另需 TCP 80，不代表 HY2 业务端口使用 TCP。")
add("内部端口（交易系统）", "交易系统的网页入口会把请求转给内部 TCP 服务，默认 TCP 18880，仅服务器本机使用。\n\n它不能和网页端口相同，通常保持推荐值即可；服务器防火墙和云平台安全组均不需要向公网开放这个内部端口。")
add("生成密码|生成口令", "只为当前的新密码或新私钥口令生成安全随机值，不会立即修改服务器。密码为 40 个字符，私钥口令为 48 个字符；使用操作系统的密码学安全随机源，不是时间戳或普通随机数。账号页的确认密码同步填写。\n\n生成只填表单，尚未保存；仍须预览、确认执行。普通账号新密码在提交前存入本机钥匙串副本，项目密码和加密密钥沿用原安全保存与验证流程。已有登录密码、旧私钥口令和旧面板备忘必须填写实际旧值，不能用随机新值代替。")
add("查看本次新密码", "选中创建管理员或修改系统密码的记录，从本机钥匙串取回本次填写的新密码，默认隐藏，可以主动显示或复制。未选中时先列出当前服务器的本机记录，再选中查看，不需要连接服务器，也不会再设置密码。\n\n副本在提交前保存，所以未完成、失败或恢复的任务里，新密码不一定已经生效，必须核对结果；它不会提前覆盖原登录密码。仅适用于本次更新后的操作，旧记录不补生成。删除账号时会清理当前本机操作记录对应的副本。入口跟随当前保留的本机记录，不代替长期安全备份。")
add("面板账号（代理面板）|服务密码（代理服务）", "代理面板账号用于登录管理网页；代理服务密码用于客户端连接代理。它们和 Linux 登录账号、密码不同。\n\n生成密码会填入一个随机口令，部署前还需确认。需要使用时，可以在连接信息窗口主动显示或复制。")
add("面板密码", "这是代理管理面板的登录密码，与 Linux 登录密码、交易系统程序密码不同。\n\n可以自行填写或点击生成密码。它只在选择代理管理面板时使用。")
add("可选设置|收起可选设置", "通常无需填写，保持默认值即可。展开后可以使用域名、修改交易系统内部端口，或选择指定安装版本。只显示所选项目适用的设置。\n\n留空的域名自动使用当前连接的服务器地址；交易系统内部端口默认为 18880；交易系统默认获取官方最新稳定版。收起不会清空填写内容，也不会执行部署。")
add("版本选择|安装版本", "首次安装默认获取官方最新稳定版；已有项目默认「保持当前版本」，单改端口不会顺带升级。选择最新稳定版或指定版本后，会先显示准确目标版本，再由你确认。指定更低版本就是降级。\n\n三款项目从官方 GitHub 获取经校验的稳定发行包；Nginx 使用服务器系统仓库的完整软件包版本，仓库不存在的版本不能安装。版本切换保留原项目配置、账号、节点及业务数据，新版本检查失败会恢复。目标版本若不兼容原数据或节点，程序会停止并恢复，不能清空数据迁就旧版本。")
add("账号所属服务器", "先选择服务器，再看它的用户和登录策略。同一台服务器保存多个登录账号时，用户列表只显示一份。\n\n切换服务器会清空上一台的用户信息，并重新读取所选服务器。不会把另一台服务器的账号用于删除或修改操作。")
add("刷新项目信息", "重新读取当前服务器、当前项目的网址、端口、TCP / UDP 协议、服务状态和连接信息。不会重新安装或修改项目。\n\nHY2 节点明确标为 UDP；代理面板的网页、订阅及各节点端口分别显示，TCP + UDP 表示两者都需放行。节点协议无法识别时提示核对，不会猜测协议或自动开放端口。Nginx 已运行的自定义入口按实际 TCP / UDP 监听显示。\n\n代理面板旧密码不能从服务器反推；本程序安装时会记在本机钥匙串，旧项目可以点击「补充登录信息」保存一份。")
add("复制选中项|复制全部项目信息", "选中一行后复制完整内容，也可以一次复制当前项目的所有信息。节点和订阅链接可以直接粘贴到代理客户端。\n\n密码和节点凭据只在本机展示与复制。右上角隐藏开关只影响显示，复制仍是原始内容。不要把剪贴板信息发到聊天或不可信网站。")
add("打开项目网址", "打开所选项目的网页入口。交易系统打开软件网址；代理管理面板打开它的独立后台路径。\n\nHysteria2 没有网页后台，使用复制的节点链接连接。云平台安全组还需放行对应业务端口。")
add("补充登录信息|保存本机记录", "把旧代理面板的账号和密码保存到这台电脑的钥匙串，日常维护页就能显示和复制。\n\n这只是本机备忘，不会重设服务器或面板密码，也不会发送到外部服务。填错可以重新保存。")
add("查看访问 / 连接信息|复制|打开管理网页", "查看项目网址、初始化码或代理连接信息。敏感内容默认隐藏，你可以主动显示、复制或打开网页。\n\n复制会把内容放进这台电脑的剪贴板，请不要发到聊天或不可信网站。这个操作不会修改服务器配置。")
add("安装与配置|安装 / 调整配置", "打开当前项目的安装和配置页面。首次安装按表单填写；已有项目会带入最近检查到的配置，默认保持当前版本。这里只切换页面，不会立即安装、重启或修改服务器。\n\n确认参数后点击预览并部署，程序会列出实际变化，再由你确认执行。原有升级、降级、备份和失败恢复功能保留。")
add("运行与备份|管理选中项目", "打开所选项目的日常管理，可以查看网址与连接信息、启停服务、读取日志和备份配置。总览中尚未安装的项目会打开安装表单。\n\n切换页面和选择项目不会自动修改服务器，也不会清空其他功能。交易系统停机或升级前仍需在业务网页停止交易并完成清理。")
add("管理已安装的服务|要管理的项目", "选中项目后，只对这个项目执行启停、日志或备份操作。先确认当前服务器，再确认项目名称。\n\nNginx 启停及配置恢复只操作 nginx.service 共享核心，会影响该核心下的其他网站，不操作交易系统的专属网页入口；交易入口随小军交易系统管理。\n\n交易系统停止或重启前，先在业务网页停止任务、完成撤单和清理，避免中断正在进行的业务。")
add("查看运行日志", "查看所选项目的启动、停止、失败等系统记录，便于判断服务有没有正常运行。\n\n为保护口令，程序只显示经过筛选的服务生命周期记录。具体业务日志到项目管理网页里查看。")
add("启动", "启动选中的项目服务。如果它已经运行，系统通常不会重复启动第二份。\n\n启动服务不等于开始交易任务，也不会修改项目内的业务规则。")
add("停止", "关闭所选项目的服务，对应网页或代理暂时不可用。\n\n停止交易系统前，必须先在交易网页停止任务并完成撤单、清理。它不会删除项目文件或数据。")
add("卸载所选项目", "真正移除所选项目的程序和专属系统服务，不只是停止。点击后先检查归属并预览移除范围，确认才执行；默认保留配置、账号、交易账本、节点和证书，之后可重新安装复用。没有本程序安装记录、自定义服务或其他服务引用项目时会拒绝自动卸载。\n\n交易系统必须先在业务网页停止所有交易、完成撤单和清理，程序不能代替你核对订单。系统 SSH 账号、本机口令、共享软件包、证书续期工具和防火墙规则不删除。Nginx 仅移除本程序创建的独立站点，保留共享核心及其他网站。\n\n移除文件放入服务器管理员专用任务目录用于失败恢复，备份仍占磁盘，不保证释放空间。失败会尝试恢复；异常中断或恢复失败可在操作记录选中任务，再点击「恢复待验证变更」。已完成卸载不能用此按钮随意撤销；重装从安装与配置进入。重要数据仍需单独安全备份。")
add("重启", "先停止再启动所选服务，常用于让配置重新加载。这个过程中网页或代理会短暂断开。\n\n交易系统先停止业务任务并完成清理，再安排重启。它不会自动升级项目版本。")
add("开启开机启动|关闭开机启动", "决定服务器重新开机后，这个服务会不会自动启动。\n\n它和现在立刻启动、停止是两回事。关闭开机启动不会立刻结束当前正在运行的服务。")
add("备份所选服务配置|备份安全配置", "把配置保存一份到服务器的管理员专用目录，并生成备份编号。以后配置改错时，可以按编号恢复。\n\n安全备份含 SSH、防火墙及本程序的防猜密码、自动更新配置。账号禁用和删除只能使用原任务的恢复机制。它不是服务器镜像，不含交易账本，敏感备份仅管理员可读。")
add("备份编号|预览并恢复配置", "填写之前保存的配置备份编号。恢复时，程序先再备份当前配置，再恢复所选备份里的内容。\n\n恢复某些服务配置会短暂重启所选服务。安全连接会再次验证。交易账本等业务数据不会被这个功能覆盖。")
add("进度、结果与恢复记录|刷新记录", "查看当前服务器的后台操作有没有完成、失败或恢复。断线后重新连接并刷新，可以继续查看结果。\n\n提交前本机先保存任务编号，响应丢失先核对原任务；短暂中断只重连查结果，不重跑已完成步骤。每次最多尝试 4 次，持续不可达会停止并保留记录。‘提交未确认’不代表失败或未执行，先核对，不能直接重跑整个方案。身份变化或认证失败会停止重试，等待核实。")
add("查看任务详情", "选中一条记录，查看它执行到哪一步，以及失败时的脱敏诊断。\n\n任务详情只读取记录，不会重新执行同一个操作。")
add("恢复待验证变更", "对还在等待连接验证的账号或连接配置，主动恢复到变更前的备份。也可恢复异常中断或恢复未完成的卸载：找回项目文件，恢复原服务状态，不清空业务数据，不覆盖新安装。\n\n部署回滚未完成时，可按原任务的部署备份再次恢复原项目、配置、证书钩子和服务状态，核验开机启动及运行状态；仍失败会明确保留需处理状态。恢复可能短暂停机，交易系统须先停止交易并完成撤单与清理。\n\n已经完成的任务不能用这个按钮随意撤销。连不上时，服务器端保护任务会尝试恢复；云平台控制台仍是备用入口。")
add("安全方案类型|修改现有用户名和密钥|新增管理员和密钥", "修改现有：对当前登录的普通管理员换名字、换一把新的加密钥匙；名称不变就只换钥匙。账号编号和原有文件权限保留，运行业务的账号会拒绝改名。\n\n新增管理员：建立另一个普通管理员和独立密钥，验证后保存为另一条本机连接。原账号可以禁止登录，文件仍保留。超级管理员请选择新增模式。")
add("目标账号名", "这是安全方案完成后使用的 Linux 登录名。修改模式可以填写新名字，也可以填现在的名字只换密钥。新增模式必须填写尚不存在的名字。\n\n使用小写字母、数字、下划线或连字符，以小写字母或下划线开头，最多 32 位。先确认已连接的是你要配置的服务器。")
add("系统新密码（可留空）", "新增模式留空时，程序生成很长的随机密码并保存到本机钥匙串，供管理员操作使用。修改模式留空时，现有系统密码保持不变；要更换可点击旁边的「生成密码」，确认执行后才生效。\n\n填写则至少 12 位。方案会关闭 SSH 密码入口，但系统密码仍可能用于 sudo 或云平台控制台，它与私钥口令不是一回事。")
add("加密私钥口令（可留空）", "给本机私钥再加一层密码保护，别人只拿到文件也不能直接使用。至少 16 位，点击「生成口令」填入 48 字符随机口令，留空也会自动生成。\n\n程序先验证本机钥匙串确实能保存口令，再配置服务器。私钥和口令都留在这台电脑。记住登录后不必每次输入；换电脑要自行迁移和备份。")
add("验证后撤销原档案旧钥匙", "修改模式下，先用新钥匙成功登录并验证管理员权限，再从该账号撤销原连接档案对应的公钥。原私钥文件保留，但不能再开这台服务器的这扇门。\n\n其他公钥不会删除。原来使用密码登录、没有旧私钥时，这个选项没有可撤销对象。其他电脑若共用旧钥匙，也会受影响。")
add("新增后禁止原账号登录", "仅新增模式使用。新管理员和密钥实际验证成功后，禁止原普通账号通过 SSH 登录并锁住其系统密码。原账号及文件保留。\n\n超级管理员由方案的 SSH 策略禁止直接登录，不会删除。需要恢复原普通账号时，在账号列表里选中并点击恢复用户登录。已有会话不会强制退出。")
add("方案中启用防猜密码保护", "一键方案里开启 Fail2ban：某地址在 10 分钟内登录失败 5 次，临时封禁 60 分钟，之后自动解除。它不是固定来源地址白名单，换网络仍可正常登录。\n\n已有其他防护规则保留。安装需要服务器软件源可用；这一步失败时，前面已经验证完成的账号和密钥仍保留。")
add("方案中启用自动安全更新", "启用并核验系统安全补丁的实际定时调度，从下一次计划开始，自动重启保持关闭。它不负责切换你安装的交易系统或其他业务项目版本。\n\n软件源策略或定时器故障可能让这一步失败，程序会告诉你哪些步骤已完成，不会为了这一步撤销已经验证的新登录账号。")
add("预览并应用一键安全方案", "先选修改或新增账号，填目标名字，其余口令可自动生成。点击后先列出本次改动，确认后逐步执行；新的密钥和管理员权限验证成功才关闭密码入口。\n\n不新增固定来源地址限制，不改变现有端口和隧道转发。每个连接步骤有自己的备份和超时恢复；后续安装失败时，已完成步骤保留。系统和复杂自定义 SSH 配置不兼容时会在开始前提示。")
add("显示系统账号", "Linux 为后台服务创建很多系统账号，它们和人使用的管理员账号不同。勾选后可以查看全部账号，总数始终包括它们。\n\n系统账号、超级管理员和当前账号不能通过删除按钮删除。不要把系统账号数量多当成有人入侵。此选项只改变列表显示。")
add("刷新用户列表", "重新读取服务器上的全部本机用户、用户组、密码状态和安全设置。不会创建、改名或删除账号。\n\n列表是最近一次读取结果；其他人可能同时修改服务器，所以真正删除前程序还会在服务器上检查账号、进程、服务和管理员权限。")
add("查看选中账号详情", "选中列表里的账号，查看登录名、用户编号、组、家目录、Shell、密码状态、管理员规则和按账号查询的 SSH 策略。来源地址使用当前连接；涉及主机名等特殊条件仍需核对。\n\n服务器只保存公钥。本机私钥位置来自本机保存的连接档案，无法显示别的电脑的私钥位置。默认隐藏信息，可用右上角开关查看。")
add("复制选中账号信息", "将选中账号的登录名、安全策略和本机已知私钥位置复制到这台电脑的剪贴板。不会复制密码、私钥口令或私钥内容。\n\n信息可能包含真实账号和路径，请不要发给不可信网站或聊天。先点击查看详情能复制更完整的按账号策略；否则会标明只是全局概览。")
add("删除选中用户（保留文件）", "直接删除列表中选中的普通账号，默认保留家目录和文件。不能删除系统账号、超级管理员、当前正在使用的账号。\n\n必须用另一个普通管理员连接。程序会再次验证备用管理员；目标账号存在进程、服务、定时任务或重要引用时会拒绝删除。确认框会展示真正要删除的账号，删除后清除它在本机保存的登录口令。")
add("自定义设置|收起自定义设置", "默认收起逐项设置，让一键登录安全方案更容易找到。需要单独调整防火墙、SSH 认证次数或防猜密码规则时，点击展开。\n\n展开和收起只改变界面，不会执行安全配置，也不会清空你填好的选项。选择后仍要点击对应应用按钮并确认，才能修改服务器。")
